dslRule:
/*!
@id: eclipse.jdt.infoviews.GetInputRename
@description: Renames calls to AbstractInfoView.getInput() to AbstractInfoView.getOrignalInput() for clarity.
@severity: INFO
@tags: renaming, api-modernization
*/
$obj.getInput() :: subtypeOf($obj, "org.eclipse.jdt.internal.ui.infoviews.AbstractInfoView")
=> $obj.getOrignalInput()
;;

beforeExample:
package org.eclipse.jdt.internal.ui.infoviews;
import org.eclipse.jdt.core.IJavaElement;
public class AbstractInfoView {
    protected IJavaElement fCurrentViewInput;
    protected IJavaElement getInput() {
        return fCurrentViewInput;
    }
    public void exampleMethod() {
        IJavaElement element = getInput();
        System.out.println(element);
    }
}
class JavadocView extends AbstractInfoView {
    public void anotherExampleMethod() {
        IJavaElement element = getInput();
        System.out.println(element);
    }
}

afterExample:
package org.eclipse.jdt.internal.ui.infoviews;
import org.eclipse.jdt.core.IJavaElement;
public class AbstractInfoView {
    protected IJavaElement fCurrentViewInput;
    protected IJavaElement getOrignalInput() {
        return fCurrentViewInput;
    }
    public void exampleMethod() {
        IJavaElement element = getOrignalInput();
        System.out.println(element);
    }
}
class JavadocView extends AbstractInfoView {
    public void anotherExampleMethod() {
        IJavaElement element = getOrignalInput();
        System.out.println(element);
    }
}

negativeExample:
package some.other.package;
public class SomeOtherClass {
    public Object getInput() { return null; }
    public void unrelatedMethod() {
        Object o = getInput(); // Should not be matched as SomeOtherClass is not a subtype of AbstractInfoView
        System.out.println(o);
    }
}
